package ir.orix.school.scheduling.application;

import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*; import java.util.function.Supplier; import java.util.stream.Collectors;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import ir.orix.school.audit.application.AuditService; import ir.orix.school.classroom.domain.ClassSection; import ir.orix.school.classroom.persistence.ClassSectionRepository; import ir.orix.school.enrollment.domain.Enrollment; import ir.orix.school.enrollment.persistence.EnrollmentRepository; import ir.orix.school.organization.domain.*; import ir.orix.school.organization.persistence.*; import ir.orix.school.people.domain.*; import ir.orix.school.people.persistence.*; import ir.orix.school.scheduling.domain.*; import ir.orix.school.scheduling.persistence.*; import ir.orix.school.shared.web.ApiException;

@Service
public class SchedulingService {
 private static final Set<ClassSession.Status> BLOCKING=Set.of(ClassSession.Status.PLANNED,ClassSession.Status.CONFIRMED,ClassSession.Status.IN_PROGRESS);
 private final TenantRepository tenants; private final BranchRepository branches; private final ClassSectionRepository sections; private final InstructorProfileRepository instructors; private final AcademicLocationRepository locations; private final ScheduleRuleRepository rules; private final ClassSessionRepository sessions; private final TenantMembershipRepository memberships; private final StudentProfileRepository students; private final EnrollmentRepository enrollments; private final AuditService audit; private final Clock clock;
 public SchedulingService(TenantRepository tenants,BranchRepository branches,ClassSectionRepository sections,InstructorProfileRepository instructors,AcademicLocationRepository locations,ScheduleRuleRepository rules,ClassSessionRepository sessions,TenantMembershipRepository memberships,StudentProfileRepository students,EnrollmentRepository enrollments,AuditService audit,Clock clock){this.tenants=tenants;this.branches=branches;this.sections=sections;this.instructors=instructors;this.locations=locations;this.rules=rules;this.sessions=sessions;this.memberships=memberships;this.students=students;this.enrollments=enrollments;this.audit=audit;this.clock=clock;}

 @Transactional(readOnly=true) public Catalog catalog(Long tenantId){return new Catalog(locations.findAllByTenantIdOrderByName(tenantId).stream().map(SchedulingService::locationView).toList(),rules.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().distinct().map(SchedulingService::ruleView).toList(),sessions.findAllByTenantIdOrderByPlannedStartAtAsc(tenantId).stream().distinct().map(SchedulingService::sessionView).toList());}
 @Transactional public LocationView createLocation(Long tenantId,Long actorId,LocationCommand c){if(locations.existsByTenantIdAndCodeIgnoreCase(tenantId,c.code()))throw conflict("LOCATION_CODE_EXISTS","Location code already exists.");Branch branch=branches.findByIdAndTenantId(c.branchId(),tenantId).orElseThrow(notFound("BRANCH_NOT_FOUND"));AcademicLocation value=locations.save(new AcademicLocation(tenant(tenantId),branch,c.code(),c.name(),c.type(),c.capacity()));audit.record(tenantId,actorId,"LOCATION_CREATED","ACADEMIC_LOCATION",value.getId(),Map.of("code",value.getCode()));return locationView(value);}
 @Transactional public RuleView createRule(Long tenantId,Long actorId,RuleCommand c){validateRule(c);if(rules.existsByTenantIdAndCodeIgnoreCase(tenantId,c.code()))throw conflict("SCHEDULE_CODE_EXISTS","Schedule code already exists.");ClassSection section=sections.findByIdAndTenantId(c.classSectionId(),tenantId).orElseThrow(notFound("CLASS_SECTION_NOT_FOUND"));AcademicLocation location=c.locationId()==null?null:locations.findByIdAndTenantId(c.locationId(),tenantId).orElseThrow(notFound("LOCATION_NOT_FOUND"));LinkedHashSet<InstructorProfile> assigned=c.instructorIds().stream().map(id->instructors.findByIdAndTenantId(id,tenantId).orElseThrow(notFound("INSTRUCTOR_NOT_FOUND"))).collect(Collectors.toCollection(LinkedHashSet::new));ensureNoRuleConflict(tenantId,c,section,location,assigned);ScheduleRule value=rules.save(new ScheduleRule(tenant(tenantId),section,c.code(),c.recurrenceType(),c.startsOn(),c.endsOn(),c.dayOfWeek(),c.startsAt(),c.endsAt(),c.timeZone(),c.intervalWeeks(),location,assigned));audit.record(tenantId,actorId,"SCHEDULE_RULE_CREATED","SCHEDULE_RULE",value.getId(),Map.of("code",value.getCode()));return ruleView(value);}
 @Transactional public List<SessionView> generate(Long tenantId,Long actorId,Long ruleId,LocalDate throughDate){ScheduleRule rule=rules.findByIdAndTenantId(ruleId,tenantId).orElseThrow(notFound("SCHEDULE_RULE_NOT_FOUND"));LocalDate today=LocalDate.now(clock);LocalDate through=throughDate==null?today.plusMonths(3):throughDate;if(through.isBefore(today))throw invalid("INVALID_GENERATION_RANGE","Generation end cannot be before today.");List<ClassSession> created=new ArrayList<>();for(LocalDate date:ScheduleOccurrenceCalculator.dates(rule,today,through)){if(sessions.existsByScheduleRuleIdAndSessionDate(rule.getId(),date))continue;ZoneId zone=ZoneId.of(rule.getTimeZone());ClassSession candidate=new ClassSession(tenant(tenantId),rule.getClassSection(),rule,date,date.atTime(rule.getStartsAt()).atZone(zone).toInstant(),date.atTime(rule.getEndsAt()).atZone(zone).toInstant(),rule.getLocation(),rule.getInstructors());ensureNoSessionConflict(tenantId,candidate,null);created.add(sessions.save(candidate));}audit.record(tenantId,actorId,"SESSIONS_GENERATED","SCHEDULE_RULE",rule.getId(),Map.of("count",created.size(),"throughDate",through.toString()));return created.stream().map(SchedulingService::sessionView).toList();}
 @Transactional public SessionView cancel(Long tenantId,Long actorId,Long id,String reason){ClassSession value=sessions.findByIdAndTenantId(id,tenantId).orElseThrow(notFound("SESSION_NOT_FOUND"));if(!BLOCKING.contains(value.getStatus()))throw conflict("SESSION_NOT_CHANGEABLE","Only an upcoming or active session can be cancelled.");value.cancel(reason);audit.record(tenantId,actorId,"SESSION_CANCELLED","CLASS_SESSION",id,Map.of("reason",reason));return sessionView(value);}
 @Transactional public SessionView reschedule(Long tenantId,Long actorId,Long id,RescheduleCommand c){ClassSession original=sessions.findByIdAndTenantId(id,tenantId).orElseThrow(notFound("SESSION_NOT_FOUND"));if(!BLOCKING.contains(original.getStatus()))throw conflict("SESSION_NOT_CHANGEABLE","Only an upcoming or active session can be rescheduled.");if(!c.endsAt().isAfter(c.startsAt()))throw invalid("INVALID_SESSION_TIME","End time must be after start time.");ZoneId zone=zone(c.timeZone());ClassSession replacement=new ClassSession(tenant(tenantId),original.getClassSection(),null,c.sessionDate(),c.sessionDate().atTime(c.startsAt()).atZone(zone).toInstant(),c.sessionDate().atTime(c.endsAt()).atZone(zone).toInstant(),original.getLocation(),original.getInstructors());ensureNoSessionConflict(tenantId,replacement,original.getId());replacement=sessions.save(replacement);original.replacedBy(replacement,c.reason());audit.record(tenantId,actorId,"SESSION_RESCHEDULED","CLASS_SESSION",id,Map.of("replacementSessionId",replacement.getId().toString(),"reason",c.reason()));return sessionView(replacement);}
 @Transactional(readOnly=true) public List<SessionView> mine(Long tenantId,Long membershipId){TenantMembership membership=memberships.findByIdAndTenantId(membershipId,tenantId).orElseThrow(notFound("MEMBERSHIP_NOT_FOUND"));StudentProfile student=students.findByTenantIdAndPersonId(tenantId,membership.getPerson().getId()).orElseThrow(notFound("STUDENT_PROFILE_NOT_FOUND"));return forStudent(tenantId,student.getId());}
 @Transactional(readOnly=true) public List<SessionView> forStudent(Long tenantId,Long studentId){students.findByIdAndTenantId(studentId,tenantId).orElseThrow(notFound("STUDENT_NOT_FOUND"));Set<Long> sectionIds=enrollments.findAllByTenantIdAndStudentIdOrderByCreatedAtDesc(tenantId,studentId).stream().filter(e->e.getStatus()==Enrollment.Status.ACTIVE).map(e->e.getClassSection().getId()).collect(Collectors.toSet());if(sectionIds.isEmpty())return List.of();return sessions.findAllByTenantIdAndClassSectionIdInAndPlannedEndAtAfterOrderByPlannedStartAtAsc(tenantId,sectionIds,Instant.now(clock)).stream().distinct().map(SchedulingService::sessionView).toList();}

 private void validateRule(RuleCommand c){if(c.endsOn().isBefore(c.startsOn()))throw invalid("INVALID_SCHEDULE_DATES","Schedule end cannot be before start.");if(c.recurrenceType()==ScheduleRule.RecurrenceType.ONCE&&!c.endsOn().equals(c.startsOn()))throw invalid("INVALID_ONCE_DATES","A one-time schedule must start and end on the same date.");if(ChronoUnit.DAYS.between(c.startsOn(),c.endsOn())>366)throw invalid("SCHEDULE_RANGE_TOO_LONG","Schedule range cannot exceed 366 days.");if(!c.endsAt().isAfter(c.startsAt()))throw invalid("INVALID_SCHEDULE_TIME","End time must be after start time.");if(c.intervalWeeks()<1)throw invalid("INVALID_INTERVAL","Interval must be positive.");if(c.recurrenceType()==ScheduleRule.RecurrenceType.WEEKLY&&c.dayOfWeek()==null)throw invalid("DAY_OF_WEEK_REQUIRED","Weekly schedules require a day of week.");zone(c.timeZone());}
 private void ensureNoRuleConflict(Long tenantId,RuleCommand candidate,ClassSection section,AcademicLocation location,Set<InstructorProfile> assigned){Set<Long> instructorIds=assigned.stream().map(InstructorProfile::getId).collect(Collectors.toSet());for(ScheduleRule existing:rules.findAllByTenantIdOrderByCreatedAtDesc(tenantId)){if(existing.getStatus()!=ScheduleRule.Status.ACTIVE||!resourcesOverlap(section,location,instructorIds,existing))continue;LocalDate from=max(candidate.startsOn(),existing.getStartsOn()),to=min(candidate.endsOn(),existing.getEndsOn());if(to.isBefore(from))continue;Set<LocalDate> dates=new HashSet<>(ScheduleOccurrenceCalculator.dates(candidate.recurrenceType(),candidate.startsOn(),candidate.endsOn(),candidate.dayOfWeek(),candidate.intervalWeeks(),from,to));for(LocalDate date:ScheduleOccurrenceCalculator.dates(existing,from,to)){if(dates.contains(date)&&timeOverlap(candidate.startsAt(),candidate.endsAt(),existing.getStartsAt(),existing.getEndsAt()))throw conflict("SCHEDULE_CONFLICT","Class, instructor or location already has an overlapping schedule.");}}}
 private boolean resourcesOverlap(ClassSection section,AcademicLocation location,Set<Long> instructors,ScheduleRule other){if(section.getId().equals(other.getClassSection().getId()))return true;if(location!=null&&other.getLocation()!=null&&location.getId().equals(other.getLocation().getId()))return true;return other.getInstructors().stream().anyMatch(i->instructors.contains(i.getId()));}
 private void ensureNoSessionConflict(Long tenantId,ClassSession candidate,Long excludedId){Set<Long> instructorIds=candidate.getInstructors().stream().map(InstructorProfile::getId).collect(Collectors.toSet());for(ClassSession other:sessions.findAllByTenantIdOrderByPlannedStartAtAsc(tenantId)){if(Objects.equals(other.getId(),excludedId)||!BLOCKING.contains(other.getStatus())||!instantOverlap(candidate,other))continue;boolean conflict=candidate.getClassSection().getId().equals(other.getClassSection().getId())||candidate.getLocation()!=null&&other.getLocation()!=null&&candidate.getLocation().getId().equals(other.getLocation().getId())||other.getInstructors().stream().anyMatch(i->instructorIds.contains(i.getId()));if(conflict)throw conflict("SESSION_CONFLICT","Class, instructor or location already has an overlapping session.");}}
 private static boolean instantOverlap(ClassSession a,ClassSession b){return a.getPlannedStartAt().isBefore(b.getPlannedEndAt())&&b.getPlannedStartAt().isBefore(a.getPlannedEndAt());} private static boolean timeOverlap(LocalTime as,LocalTime ae,LocalTime bs,LocalTime be){return as.isBefore(be)&&bs.isBefore(ae);} private static LocalDate max(LocalDate a,LocalDate b){return a.isAfter(b)?a:b;} private static LocalDate min(LocalDate a,LocalDate b){return a.isBefore(b)?a:b;} private static ZoneId zone(String id){try{return ZoneId.of(id);}catch(DateTimeException e){throw invalid("INVALID_TIME_ZONE","Time zone must be a valid IANA identifier.");}}
 private Tenant tenant(Long id){return tenants.findById(id).orElseThrow(notFound("TENANT_NOT_FOUND"));} private static Supplier<ApiException> notFound(String code){return ()->new ApiException(HttpStatus.NOT_FOUND,code,"The requested scheduling item was not found.");} private static ApiException invalid(String code,String detail){return new ApiException(HttpStatus.BAD_REQUEST,code,detail);} private static ApiException conflict(String code,String detail){return new ApiException(HttpStatus.CONFLICT,code,detail);}
 private static LocationView locationView(AcademicLocation l){return new LocationView(l.getId(),l.getBranch().getId(),l.getBranch().getName(),l.getCode(),l.getName(),l.getType().name(),l.getCapacity(),l.getStatus().name());}
 private static RuleView ruleView(ScheduleRule r){return new RuleView(r.getId(),r.getClassSection().getId(),r.getClassSection().getName(),r.getCode(),r.getRecurrenceType().name(),r.getStartsOn(),r.getEndsOn(),r.getDayOfWeek()==null?null:r.getDayOfWeek().name(),r.getStartsAt(),r.getEndsAt(),r.getTimeZone(),r.getIntervalWeeks(),r.getLocation()==null?null:r.getLocation().getId(),r.getLocation()==null?null:r.getLocation().getName(),r.getInstructors().stream().map(i->new InstructorView(i.getId(),i.getPerson().getFullName())).toList(),r.getStatus().name());}
 private static SessionView sessionView(ClassSession s){return new SessionView(s.getId(),s.getClassSection().getId(),s.getClassSection().getName(),s.getClassSection().getOffering().getCourse().getTitle(),s.getClassSection().getOffering().getBranch().getName(),s.getScheduleRule()==null?null:s.getScheduleRule().getId(),s.getSessionDate(),s.getPlannedStartAt(),s.getPlannedEndAt(),s.getLocation()==null?null:s.getLocation().getName(),s.getInstructors().stream().map(i->new InstructorView(i.getId(),i.getPerson().getFullName())).toList(),s.getStatus().name(),s.isManuallyOverridden(),s.getChangeReason(),s.getReplacementSession()==null?null:s.getReplacementSession().getId());}
 public record LocationCommand(Long branchId,String code,String name,AcademicLocation.Type type,Integer capacity){} public record RuleCommand(Long classSectionId,String code,ScheduleRule.RecurrenceType recurrenceType,LocalDate startsOn,LocalDate endsOn,DayOfWeek dayOfWeek,LocalTime startsAt,LocalTime endsAt,String timeZone,int intervalWeeks,Long locationId,Set<Long> instructorIds){} public record RescheduleCommand(LocalDate sessionDate,LocalTime startsAt,LocalTime endsAt,String timeZone,String reason){}
 public record LocationView(Long id,Long branchId,String branchName,String code,String name,String type,Integer capacity,String status){} public record InstructorView(Long id,String name){} public record RuleView(Long id,Long classSectionId,String className,String code,String recurrenceType,LocalDate startsOn,LocalDate endsOn,String dayOfWeek,LocalTime startsAt,LocalTime endsAt,String timeZone,int intervalWeeks,Long locationId,String locationName,List<InstructorView> instructors,String status){} public record SessionView(Long id,Long classSectionId,String className,String courseTitle,String branchName,Long scheduleRuleId,LocalDate sessionDate,Instant plannedStartAt,Instant plannedEndAt,String locationName,List<InstructorView> instructors,String status,boolean manuallyOverridden,String changeReason,Long replacementSessionId){} public record Catalog(List<LocationView> locations,List<RuleView> rules,List<SessionView> sessions){}
}
